def main() -> None:
    TRANSLATIONS.update(STORY_TRANSLATIONS)
    destination = ROOT / "translations/batch97.json"
    if destination.exists():
        raise FileExistsError(destination)
    records = collect_messages(Rom(rom_paths()["blue"]))
    existing = translate_records(records)
    blocks = []
    for entry, translations in TRANSLATIONS.items():
        for index, english in sorted(translations.items()):
            key = f"MSG/MESPAK02.PAK:{entry:03d}:{index:05d}"
            if key not in records or key in existing:
                raise ValueError(f"Missing or already translated source: {key}")
            row = records[key]
            if category(row) != "Story and dialogue":
                raise ValueError(f"Unexpected category for {key}: {category(row)}")
            sources = ["Original Japanese ROM", "Existing reviewed project glossary"]
            if "SkullMammothmon" in english:
                sources.append("https://world.digimoncard.com/cards/?card_no=BT6-043&search=true")
            if "SkullBaluchimon" in english:
                sources.append("https://world.digimoncard.com/cards/?card_no=BT10-080&search=true")
            if "HerculesKabuterimon" in english:
                sources.append("https://world.digimoncard.com/cards/?card_no=ST4-013&search=true")
            if "Zanahoria" in english or "Sparrowmon" in english:
                sources.append("https://digimon.net/reference_en/detail.php?directory_name=sparrowmon")
            if "Mjolnir Thunder" in english:
                sources.append("https://digimon.net/reference_en/detail.php?directory_name=parrotmon")
            if "Rose Rapier" in english:
                sources.append("https://digimon.fandom.com/wiki/Digimon_World_Dawn_and_Dusk/Attacks")
            if "Vee Head Butt" in english:
                sources.append("https://www.videogamemanual.com/ps1/Digimon%20World%202%20%28USA%29.pdf")
            blocks.append({
                "archive": row["archive"], "entry": row["entry"],
                "start": row["index"], "category": "Story and dialogue",
                "english": [english],
                "sources": sources,
                "review_note": "Side-story and Farm dialogue. Human names and game locations follow the project style guide; established Digimon names use the reviewed Western-name glossary. Story lines are automatically wrapped by the build at the fixed 15-column limit.",
            })
    destination.write_text(json.dumps({
        "description": "Translate optional missions, NPC dialogue, tournament banter, and Farm conversations.",
        "blocks": blocks,
    }, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(json.dumps({"output": str(destination), "slots": len(blocks)}, ensure_ascii=False))


if __name__ == "__main__":
    main()
